<div class="admin-page-actions"><form class="admin-search" method="get" action="/admin/konten"><input type="hidden" name="type" value="<?= e($type) ?>"><label class="sr-only" for="content-search">Cari konten</label><input id="content-search" type="search" name="q" value="<?= e($query) ?>" placeholder="Cari judul, slug, kategori…"><button type="submit">Cari</button></form><?php if ($canEdit): ?><a class="button button-primary" href="/admin/konten/tambah?type=<?= e($type) ?>">＋ Tambah <?= e(strtolower($pageTitle)) ?></a><?php endif; ?></div>
<div class="admin-panel table-panel"><div class="admin-panel-heading"><div><p class="eyebrow">DAFTAR KONTEN</p><h2><?= e($pageTitle) ?></h2></div><span class="table-count"><?= (int) $total ?> data</span></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Judul</th><th>Kategori</th><th>Status</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody><?php if ($items): foreach ($items as $item): ?><tr><td><strong><?= e($item['title']) ?></strong><small>/<?= e($item['slug']) ?></small></td><td><?= e($item['category'] ?: '—') ?></td><td><span class="status-pill status-<?= e($item['status']) ?>"><?= e(['draft'=>'Draft','published'=>'Terbit','archived'=>'Arsip'][$item['status']] ?? $item['status']) ?></span></td><td><?= e(format_date($item['updated_at'])) ?></td><td class="table-actions"><?php if ($canEdit): ?><a href="/admin/konten/<?= (int) $item['id'] ?>/edit">Ubah</a><?php endif; ?><?php if (in_array($user['role'], ['super_admin','editor'], true)): ?><form method="post" action="/admin/konten/<?= (int) $item['id'] ?>/hapus" data-confirm="Hapus konten ini? Tindakan ini tidak dapat dibatalkan."><?= csrf_field() ?><button type="submit" class="text-danger">Hapus</button></form><?php endif; ?><?php if ($item['status'] === 'published'): ?><a href="<?= e(content_url($type, $item['slug'])) ?>" target="_blank" rel="noopener">Lihat ↗</a><?php endif; ?></td></tr><?php endforeach; else: ?><tr><td colspan="5"><div class="table-empty"><strong>Belum ada konten.</strong><span>Tambahkan informasi pertama untuk bagian ini.</span></div></td></tr><?php endif; ?></tbody></table></div>
<?php if ($pages > 1): ?><div class="admin-pagination"><?php for ($i=1;$i<=$pages;$i++): ?><a href="?type=<?= e($type) ?>&q=<?= rawurlencode($query) ?>&page=<?= $i ?>" <?= $i === $page ? 'aria-current="page"' : '' ?>><?= $i ?></a><?php endfor; ?></div><?php endif; ?></div>
